import 'dart:convert';import 'package:flutter_test/flutter_test.dart';import 'package:http/http.dart' as http;import 'package:http/testing.dart';import 'package:fluxidi_tracking/customer_booking/reliable_choice_api.dart';
Map<String,dynamic> row()=>{'schema':'fluxidi-reliable-choice-v1','vehicle_id':'V','vehicle_name':'Vito','estimate':true,'graph_version':'real-graph','evidence_revision':'r','valid_until_ms':20000,'status':'available_for_selected_time','pickup_eta_seconds':null,'pickup_eta_range_seconds':null,'pickup_distance_meters':null,'driver_id':'PRIVATE'};
void main(){
 test('P22 canonical return DTO whitelists planned availability, no now ETA or driver context',()async{final client=MockClient((_)async=>http.Response(jsonEncode({'ok':true,'schema':'fluxidi-reliable-choice-v1','selection_token':'00000000-0000-0000-0000-000000000000','vehicles':[],'return_vehicles':[row()]}),200)),api=ReliableChoiceApiV1(base:Uri.parse('https://local-fixture'),token:'customer',client:client);final parsed=await api.prebooking({},nowMs:1000);expect(parsed.returnVehicles.single['status'],'available_for_selected_time');expect(parsed.returnVehicles.single['pickup_distance_meters'],isNull);expect(parsed.returnVehicles.single.containsKey('driver_id'),false);client.close();});
 for(final patch in [{'pickup_eta_seconds':300},{'pickup_distance_meters':1000},{'valid_until_ms':1000},{'graph_version':''},{'vehicle_id':'INVALID/'},{'status':'live'}])test('P22 malformed return evidence rejected $patch',()async{final client=MockClient((_)async=>http.Response(jsonEncode({'ok':true,'schema':'fluxidi-reliable-choice-v1','selection_token':'00000000-0000-0000-0000-000000000000','vehicles':[],'return_vehicles':[{...row(),...patch}]}),200));final api=ReliableChoiceApiV1(base:Uri.parse('https://local-fixture'),token:'customer',client:client);await expectLater(api.prebooking({},nowMs:1000),throwsStateError);client.close();});
}
